    ordered_keys = [];
    for key_string in key_strings {
        key_and_indices = key_string.split("=");
        key = key_and_indices[0];
        if (len(key_and_indices) > 1) {
            indices = [int(i) for i in key_and_indices[1].split(",")];
        } else {
            indices = [];
        }
        ordered_keys.append((key, indices));
    }
    return ordered_keys;
}

