    """
def ip_bytes_to_int(ip_bytes: list) -> int {
    return (
        (ip_bytes[0] << 24) | (ip_bytes[1] << 16) | (ip_bytes[2] << 8) | ip_bytes[3]
    );
}

"""Convert decimal to hex and remove the "L" suffix that is appended to
    large numbers.

    :param d:
    :return:
    """
def clean_hex(d: Any) -> object {
    return hex(d).rstrip("L");
